# ── 3. 그림 2 칸마다 잰 값 ───────────────────────────────
def shade(v, lo, hi, c0, c1):
    t = max(0, min(1, (v - lo) / (hi - lo)))
    a = [int(c0[i:i + 2], 16) for i in (1, 3, 5)]
    z = [int(c1[i:i + 2], 16) for i in (1, 3, 5)]
    return "#%02X%02X%02X" % tuple(int(a[i] + (z[i] - a[i]) * t) for i in range(3))


def fig03():
    b = txt(390, 28, "원문 그림 2(a) 칸마다 내가 잰 값 (칸마다 이미지 한 장, 190 x 190 픽셀)", 15, weight=600)
    cw, ch = 44, 34
    for p, (key, title, lo, hi, c0, c1, fmt) in enumerate(((0, "낮은 주파수 몫 (반지름 1~7 / 1~94 전력)", 0, 1, "#FFFFFF", "#B4552B", "%.2f"),
                                                           (1, "초과 첨도 (가우스 분포면 0)", -1, 0, "#2E6B8A", "#FFFFFF", "%.2f"))):
        ox = 74 + p * 370
        oy = 76
        b += txt(ox + cw * 3.5, oy - 12, title, 12.5, INK2, weight=600)
        for c in range(7):
            b += txt(ox + cw * c + cw / 2, oy + ch * 7 + 18, "2^-%d" % (c + 1), 10.5, INK2)
        for r in range(7):
            b += txt(ox - 8, oy + ch * r + ch / 2 + 4, "N=%d" % (r + 1), 10.5, INK2, "end")
            for c in range(7):
                v = FIG2["%d,%d" % (r + 1, c + 1)][key]
                b += bar(ox + cw * c, oy + ch * r, cw - 1, ch - 1, shade(v, lo, hi, c0, c1))
                b += txt(ox + cw * c + cw / 2, oy + ch * r + ch / 2 + 4, fmt % v, 10.5,
                         "#FFFFFF" if (key == 0 and v > .6) or (key == 1 and v < -.65) else INK)
        # 기본값 칸
        b += box(ox + cw * 5, oy + ch * 5, cw - 1, ch - 1, "none", NO, 2.2, 0)
    b += txt(390, 362, "붉은 테두리가 원문 기본값(N = 6, ν = 2^-6). 같은 계산을 흰 잡음에 돌리면 낮은 주파수 몫은 0.0067 이다", 12, INK)
    b += txt(390, 382, "가로축은 시작 주파수 ν, 세로축은 옥타브 수 N. 초과 첨도는 N 을 늘리면 0 쪽으로 가지만 0 에 닿지 않는다", 12, INK2)
