        need = math.sqrt(max(gap, 0) / (2 / (2 - D) ** 3))
        y = y0 + 34 + i * 54
        b += txt(x0 - 14, y + 4, n, 11, col, "end", 600)
        b += circ(fx(sd), y, 6, col, col)
        b += '<path d="M%.1f,%.1f L%.1f,%.1f L%.1f,%.1f L%.1f,%.1f z" fill="none" stroke="%s" stroke-width="2"/>' % (
            fx(need), y - 7, fx(need) + 7, y, fx(need), y + 7, fx(need) - 7, y, col)
        if need > .27:
            b += txt(fx(need) - 12, y + 4, "표 %.3f / 필요 %.3f" % (sd, need), 10.5, col, "end")
        else:
            b += txt(fx(max(sd, need)) + 12, y + 4, "표 %.3f / 필요 %.3f" % (sd, need), 10.5, col, "start")
        print("  %s: D/(2-D)=%.4f, 표 IoU=%.3f, 틈 %.4f, 필요 표준편차 %.3f, 표의 ± %.3f" % (n, D / (2 - D), I, gap, need, sd))
